import type { CellStats, VerdictCounts } from './types.js';
import { readCatalogueJson } from './data.js';

/**
 * Hand-checked verdict counts per cell, generated by scripts/build-precision.mjs
 * from the label files and committed as labels/precision.json. Nothing in here
 * is typed by hand.
 */
interface PrecisionFile {
  schema: number;
  stage: string;
  cells: Array<{ rule: string; form: string; role: string } & CellStats>;
}

export const EMPTY_COUNTS: VerdictCounts = { TRUE: 0, FALSE: 0, DEBATABLE: 0 };

let loaded: { file: PrecisionFile; byKey: Map<string, CellStats> } | undefined;

export function cellKey(rule: string, form: string, role: 'spec' | 'shared' = 'spec'): string {
  return `${rule}|${form}|${role}`;
}

function load(): NonNullable<typeof loaded> {
  if (loaded) return loaded;
  const file = readCatalogueJson<PrecisionFile>('precision.json');
  const byKey = new Map<string, CellStats>();
  for (const c of file.cells) byKey.set(cellKey(c.rule, c.form, c.role as 'spec' | 'shared'), c);
  loaded = { file, byKey };
  return loaded;
}

export function precisionFile(): PrecisionFile {
  return load().file;
}

/** Stats for one cell, or undefined when no hand-checked row reaches it. */
export function cellStats(rule: string, form: string, role: 'spec' | 'shared' = 'spec'): CellStats | undefined {
  return load().byKey.get(cellKey(rule, form, role));
}
